python3 -c "
import os, base64, json

chunk_dir = '/tmp/anon_chunks'
files_info = {}

for fname in os.listdir(chunk_dir):
    if '.chunk' in fname:
        base_name = fname.rsplit('.chunk', 1)[0]
        chunk_num = int(fname.rsplit('.chunk', 1)[1])
        if base_name not in files_info:
            files_info[base_name] = {}
        with open(os.path.join(chunk_dir, fname)) as f:
            files_info[base_name][chunk_num] = f.read()

# Output manifest
manifest = {}
for base_name, chunks in sorted(files_info.items()):
    manifest[base_name] = sorted(chunks.keys())
print(json.dumps(manifest))
"
